/**
 * Helper functions used by every page (browser side).
 * Owned by the team lead (Day 0). Members do not edit this file.
 */

/**
 * Sends a request and returns the status code and the JSON body.
 *
 * @param {string} method GET, POST, PUT or DELETE.
 * @param {string} url API address, for example '/api/hospitals/search'.
 * @param {Object} [data] Object sent as JSON (not used for GET).
 * @returns {Promise<{status: number, body: Object}>} Status and body.
 */
async function sendJson( method, url, data ) {
	const options = { method: method, headers: {} };
	if ( data !== undefined ) {
		options.headers[ 'Content-Type' ] = 'application/json';
		options.body = JSON.stringify( data );
	}
	try {
		const response = await fetch( url, options );
		const body = await response.json();
		return { status: response.status, body: body };
	} catch ( error ) {
		return { status: 0, body: { success: false, message: 'Network error. Please try again later.' } };
	}
}

/**
 * Shows a message box on the page.
 *
 * @param {string} elementId Id of the message <div>.
 * @param {string} text Message text.
 * @param {string} type 'success', 'error' or 'info'.
 */
function showMessage( elementId, text, type ) {
	const box = document.getElementById( elementId );
	if ( !box ) {
		return;
	}
	box.textContent = text;
	box.className = 'message ' + type;
}

/**
 * Makes text safe before putting it inside innerHTML (stops XSS attacks).
 *
 * @param {*} text Any value.
 * @returns {string} Safe text.
 */
function escapeHtml( text ) {
	return String( text === null || text === undefined ? '' : text )
		.replace( /&/g, '&amp;' )
		.replace( /</g, '&lt;' )
		.replace( />/g, '&gt;' )
		.replace( /"/g, '&quot;' )
		.replace( /'/g, '&#39;' );
}

/**
 * Turns an object into a query string, skipping empty values.
 * encodeURIComponent is important: it turns '+' (like O+) into %2B.
 *
 * @param {Object} params Example: { city: 'Dhaka', keyword: '' }.
 * @returns {string} Example: 'city=Dhaka'.
 */
function buildQuery( params ) {
	return Object.keys( params )
		.filter( ( key ) => params[ key ] !== '' && params[ key ] !== undefined && params[ key ] !== null )
		.map( ( key ) => encodeURIComponent( key ) + '=' + encodeURIComponent( params[ key ] ) )
		.join( '&' );
}

/**
 * Asks the server who is logged in.
 *
 * @returns {Promise<Object|null>} The user object or null.
 */
async function getCurrentUser() {
	const result = await sendJson( 'GET', '/api/auth/me' );
	return result.status === 200 ? result.body.data : null;
}

/**
 * Use at the top of a page that needs login. Sends guests to the login page.
 *
 * @returns {Promise<Object|null>} The logged-in user (or null after redirect).
 */
async function requireLoginPage() {
	const user = await getCurrentUser();
	if ( user === null ) {
		window.location.href = '/login.html';
	}
	return user;
}

/** Builds the top menu on every page. */
async function buildNavbar() {
	const navbar = document.getElementById( 'navbar' );
	if ( !navbar ) {
		return;
	}
	const user = await getCurrentUser();
	const links = [
		[ 'Hospitals', '/hospital-search.html' ],
		[ 'ICU/CCU', '/icu-search.html' ],
		[ 'Recommend', '/recommendation.html' ],
		[ 'Doctors', '/doctors.html' ],
		[ 'Appointments', '/appointments.html' ],
		[ 'Payments', '/payment.html' ],
		[ 'Records', '/health-records.html' ],
		[ 'Emergency', '/emergency.html' ],
		[ 'Ambulance', '/ambulance.html' ],
		[ 'Blood', '/blood-bank.html' ],
		[ 'Vaccines', '/vaccine.html' ],
	];
	let html = '<a class="brand" href="/dashboard.html">HealthHub</a>';
	links.forEach( ( link ) => {
		html += '<a href="' + link[ 1 ] + '">' + link[ 0 ] + '</a>';
	} );
	html += '<span class="spacer"></span>';
	if ( user ) {
		html += '<span style="color:#fff;font-size:14px">' + escapeHtml( user.fullName ) + '</span>';
		html += '<a href="#" id="logoutLink">Logout</a>';
	} else {
		html += '<a href="/login.html">Login</a><a href="/register.html">Register</a>';
	}
	navbar.className = 'navbar';
	navbar.innerHTML = html;

	const logoutLink = document.getElementById( 'logoutLink' );
	if ( logoutLink ) {
		logoutLink.addEventListener( 'click', async ( event ) => {
			event.preventDefault();
			await sendJson( 'POST', '/api/auth/logout' );
			window.location.href = '/login.html';
		} );
	}
}

document.addEventListener( 'DOMContentLoaded', buildNavbar );
